with latest as (select * from web_events qualify row_number() over (partition by event_type, page order by event_time desc nulls first, id) = 1) select case when duration_sec >= 477 then 'LARGE' else 'SMALL' end as duration_sec_tier, avg(duration_sec) as avg_duration_sec, avg(duration_sec) filter (where event_type = 'search') as search_avg_duration_sec, count(distinct event_type) as distinct_event_types, count(*) filter (where page = '/cart') as cart_rows from latest group by case when duration_sec >= 477 then 'LARGE' else 'SMALL' end order by duration_sec_tier desc nulls first;
